// Streak Reminder — runs every 5 minutes, sends each streak its daily reminder once.
// Catch-up window: if the exact minute is missed (n8n restart, 5-minute grid,
// reminder time not divisible by 5), the reminder still goes out later the same
// day. A heartbeat row is written to system_flags for observability.
const base = String($env.SUPABASE_URL ?? '');
const key = String($env.SUPABASE_SERVICE_KEY ?? '');
const TG = 'REPLACE_WITH_TELEGRAM_BOT_TOKEN';
const CHAT = 'REPLACE_WITH_TELEGRAM_CHAT_ID';
const CATCHUP_MINUTES = 180;
if (!base || !key) return [{ json: { ok: false, error: 'Supabase env vars missing in the n8n environment' } }];
const HB = { apikey: key, Authorization: 'Bearer ' + key, 'Content-Type': 'application/json', Accept: 'application/json' };
const hreq = async (o) => {
  const opts = Object.assign({ returnFullResponse: true, ignoreHttpStatusErrors: true, timeout: 25000 }, o);
  try { return await this.helpers.httpRequest(opts); } catch (e) { return { statusCode: 0, body: 'ERR ' + (e && e.message ? e.message : String(e)) }; }
};
const parse = (r) => { let d = r.body; if (typeof d === 'string' && d.length) { try { d = JSON.parse(d); } catch (e) {} } return { st: r.statusCode ?? 0, d }; };
const errOf = (r) => { const d = r.d; if (d && typeof d === 'object' && (d.message || d.hint)) return String(d.message) + (d.hint ? ' — ' + String(d.hint) : ''); return String(typeof d === 'string' ? d : JSON.stringify(d || '')).slice(0, 240); };
const cairoToday = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const cairoMinutes = () => {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
  const get = (t) => Number((parts.find((p) => p.type === t) || {}).value || 0);
  return { h: get('hour'), m: get('minute') };
};
const toMinutes = (v) => {
  const m = String(v || '').match(/^(\d{1,2}):(\d{2})/);
  if (!m) return null;
  const h = Number(m[1]); const mi = Number(m[2]);
  if (h > 23 || mi > 59) return null;
  return h * 60 + mi;
};
try {
  const now = new Date();
  const today = cairoToday();
  const { h, m } = cairoMinutes();
  const nowMin = h * 60 + m;
  const hhmm = String(h).padStart(2, '0') + ':' + String(m).padStart(2, '0');
  const MOTIVE = [
    'الاستمرارية أقوى من الحماس — كمّل! 💪',
    'كل يوم خطوة صغيرة بتفرق — متكسرش السلسلة! 🔥',
    'البطل مش اللي مابيغلطش — البطل اللي مابيكسّرش السلسلة! 🏆',
    'دقيقة واحدة بتكفي — بس متسيبش السلسلة تموت! ⚡',
    'اللي بينجح بيعمل الحاجة حتى لما مش حاببها — يلا! 🚀',
    'سلسلتك بتكبر كل يوم — كمّل النهارده كمان! 📈',
    'أصعب حاجة هي البداية — وإنت بدأت خلاص! 🌟',
    'تخيل السلسلة لما تبقى 30 يوم — النهارده خطوة منهم! 🎯'
  ];
  const r = parse(await hreq({ method: 'GET', url: base + '/rest/v1/streaks?select=*&is_active=eq.true', headers: HB, json: true }));
  if (r.st <= 0 || r.st >= 300 || !Array.isArray(r.d)) return [{ json: { ok: false, error: 'تعذر الجلب: ' + errOf(r) } }];
  const dayNum = Math.floor(now.getTime() / 86400000);
  const sent = [];
  for (const s of r.d) {
    const due = toMinutes(s.reminder_time);
    if (due === null) continue;
    const late = nowMin - due;
    if (late < 0 || late > CATCHUP_MINUTES) continue;
    if (String(s.last_reminder_sent || '') === today) continue;
    const nm = String(s.name || '');
    let hsum = 0;
    for (let i = 0; i < nm.length; i++) hsum += nm.charCodeAt(i);
    const motive = MOTIVE[(dayNum + hsum) % MOTIVE.length];
    const n = Number(s.current_streak || 0);
    const head = n > 0 ? ('🔥 ' + nm + ' — سلسلة ' + n + ' يوم متواصلة!') : ('🔥 ' + nm + ' — يلا نبدأ سلسلة جديدة النهارده!');
    const text = head + '\n\n' + motive + '\n\nعملت النهارده؟';
    const kb = { inline_keyboard: [[{ text: '✅ تمّ', callback_data: 'stk|done|' + s.id }, { text: '❌ مش النهارده', callback_data: 'stk|miss|' + s.id }]] };
    const snd = parse(await hreq({ method: 'POST', url: 'https://api.telegram.org/bot' + TG + '/sendMessage', headers: { 'Content-Type': 'application/json' }, body: { chat_id: CHAT, text: text, reply_markup: kb }, json: true }));
    const okSent = snd.st > 0 && snd.st < 300 && snd.d && snd.d.ok === true;
    let marked = false;
    if (okSent) {
      const up = parse(await hreq({ method: 'PATCH', url: base + '/rest/v1/streaks?id=eq.' + encodeURIComponent(s.id), headers: Object.assign({}, HB, { Prefer: 'return=minimal' }), body: { last_reminder_sent: today, updated_at: new Date().toISOString() }, json: true }));
      marked = up.st > 0 && up.st < 300;
    }
    sent.push({ name: nm, due: s.reminder_time, late_min: late, sent: okSent, message_id: okSent ? snd.d.result.message_id : null, marked: marked });
  }
  const run = { last_run: now.toISOString(), at: hhmm, due_count: sent.length, sent: sent };
  await hreq({ method: 'POST', url: base + '/rest/v1/system_flags?on_conflict=key', headers: Object.assign({}, HB, { Prefer: 'resolution=merge-duplicates,return=minimal' }), body: { key: 'streak_reminder_last_run', value: run, updated_at: now.toISOString(), updated_by: 'streak-reminder' }, json: true });
  return [{ json: Object.assign({ ok: true }, run) }];
} catch (e) {
  return [{ json: { ok: false, error: 'خطأ: ' + String(e && e.message ? e.message : e).slice(0, 300) } }];
}
